1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser, requireAdmin, currentUser } from "./auth";
6	import { familyFor } from "./game-config";
7	import { modLoad, modCompat, type ModLoad, type Compat } from "./mod-load";
8	import { installSupport } from "./mod-install-support";
9	import { recordAudit } from "./audit";
10	import { listModComments, type ModComment } from "./mods-catalog";
11	
12	/**
13	 * Mod-manager actions.
14	 *
15	 * Customers browse the per-game mod/plugin CATALOG (GameMod) and one-click
16	 * install/uninstall onto their server. Each change writes the desired state to a
17	 * `ServerMod` row (INSTALLING / REMOVING) and enqueues a single GAME_MOD_SYNC job
18	 * that reconciles the server to that state — the same state-driven pattern as
19	 * GAME_CONFIG (worker reads the DB, no per-op payloads to trust).
20	 *
21	 * Ownership + the "one in-flight job per server" invariant mirror
22	 * lib/actions-game-config.ts.
23	 */
24	
25	async function ownedServer(serverId: string) {
26	  const user = await requireUser();
27	  const server = await db.server.findUnique({
28	    where: { id: serverId },
29	    include: { osTemplate: true, gamePlan: true },
30	  });
31	  if (!server) throw new Error("Not found");
32	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
33	  return { user, server };
34	}
35	
36	async function hasInflightJob(serverId: string): Promise<boolean> {
37	  const pending = await db.job.count({
38	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
39	  });
40	  return pending > 0;
41	}
42	
43	export type CatalogMod = {
44	  id: string;
45	  name: string;
46	  slug: string;
47	  category: string;
48	  source: string;
49	  url: string | null;
50	  description: string | null;
51	  iconUrl: string | null;
52	  paid: boolean;
53	  featured: boolean;
54	  appliesToVariant: string | null;
55	  /** install state for THIS server: null = not installed. */
56	  status: string | null;
57	  error: string | null;
58	  /* ── verified upstream facts (scripts/verify-gamemods.ts) ──────────────
59	     Every one of these is read from the mod's own source. Where a source
60	     doesn't publish something it stays null/empty and the panel says so,
61	     rather than filling the gap with a plausible-looking number. */
62	  downloads: number | null;
63	  fileBytes: number | null;
64	  dependencyCount: number;
65	  impact: string;
66	  impactNote: string | null;
67	  verified: boolean;
68	  compat: Compat;
69	  /** Null when one-click install works; the reason it doesn't, otherwise. */
70	  manualInstall: string | null;
71	};
72	
73	export type ModsView = {
74	  family: string;
75	  variant: string | null;
76	  /** catalog entries (compatible with the server's variant), grouped by category. */
77	  categories: { category: string; mods: CatalogMod[] }[];
78	  installedCount: number;
79	  busy: boolean;
80	  /** The version this server is pinned to, when its game has one. */
81	  gameVersion: string | null;
82	  /** What the installed set is asking of this server. */
83	  load: ModLoad;
84	};
85	
86	/**
87	 * Load the mod catalog for an owned game server, annotated with each mod's
88	 * install state on this server. Only mods for the server's game family and
89	 * compatible with its selected variant are returned.
90	 */
91	export async function getServerMods(
92	  serverId: string
93	): Promise<{ error?: string; view?: ModsView }> {
94	  const { server } = await ownedServer(serverId);
95	  const family = familyFor(server);
96	  if (!family) return { error: "This server doesn't support mods." };
97	
98	  const variant = server.gameVariant ?? null;
99	  /* The pinned game version lives in the per-family config blob under VERSION
100	     (a docker env var for the Minecraft images, not a server.properties key —
101	     see lib/game-config.ts). Families without one simply have no verdict. */
102	  const cfg = (server.gameConfig ?? null) as Record<string, unknown> | null;
103	  const rawVersion = cfg && typeof cfg.VERSION === "string" ? cfg.VERSION.trim() : "";
104	  // "LATEST"/"SNAPSHOT" name a moving target, not a version we can match against.
105	  const gameVersion = rawVersion && !/^(latest|snapshot)$/i.test(rawVersion) ? rawVersion : null;
106	
107	  const [catalog, installed, busy] = await Promise.all([
108	    db.gameMod.findMany({
109	      // A project that no longer resolves upstream would fail on install, so it
110	      // is not offered — see scripts/verify-gamemods.ts.
111	      where: { gameFamily: family, active: true, upstreamOk: true },
112	      orderBy: [{ featured: "desc" }, { popularity: "desc" }, { name: "asc" }],
113	      // Cap at CATALOG_LIST_CAP (lib/mods-catalog.ts) — scripts/import-modrinth-catalog.ts
114	      // can put thousands of real rows in one family; this panel renders every
115	      // row client-side (ModsPanel.tsx), so an unbounded findMany here is the
116	      // same "small catalogue" assumption that broke, just on the per-server
117	      // install UI instead of the marketing browse page. Best mods still show
118	      // first thanks to the ordering above.
119	      take: 400,
120	    }),
121	    db.serverMod.findMany({ where: { serverId } }),
122	    hasInflightJob(serverId),
123	  ]);
124	
125	  const stateByMod = new Map(installed.map((m) => [m.modId, m]));
126	
127	  // Hide mods that target a different loader/variant than the server runs.
128	  const compatible = catalog.filter(
129	    (m) => !m.appliesToVariant || !variant || m.appliesToVariant === variant
130	  );
131	
132	  const byCategory = new Map<string, CatalogMod[]>();
133	  for (const m of compatible) {
134	    const st = stateByMod.get(m.id);
135	    const row: CatalogMod = {
136	      id: m.id,
137	      name: m.name,
138	      slug: m.slug,
139	      category: m.category,
140	      source: m.source,
141	      url: m.url,
142	      description: m.description,
143	      iconUrl: m.iconUrl,
144	      paid: m.paid,
145	      featured: m.featured,
146	      appliesToVariant: m.appliesToVariant,
147	      status: st?.status ?? null,
148	      error: st?.error ?? null,
149	      downloads: m.downloads,
150	      fileBytes: m.fileBytes,
151	      dependencyCount: m.dependencyCount,
152	      impact: m.impact,
153	      impactNote: m.impactNote,
154	      verified: m.verifiedAt !== null,
155	      manualInstall: (() => {
156	        const sup = installSupport(family, m.source);
157	        return sup.ok ? null : sup.message;
158	      })(),
159	      compat: modCompat(
160	        { gameVersions: m.gameVersions, loaders: m.loaders, serverSide: m.serverSide },
161	        { gameVersion, variant },
162	      ),
163	    };
164	    const arr = byCategory.get(m.category) ?? [];
165	    arr.push(row);
166	    byCategory.set(m.category, arr);
167	  }
168	
169	  const categories = [...byCategory.entries()]
170	    .map(([category, mods]) => ({ category, mods }))
171	    .sort((a, b) => a.category.localeCompare(b.category));
172	
173	  const live = installed.filter((m) => m.status === "INSTALLED" || m.status === "INSTALLING");
174	  const byId = new Map(catalog.map((m) => [m.id, m]));
175	  const load = modLoad({
176	    // The game plan is what the customer bought and what sizes the VM; the base
177	    // plan only backs it. Falling back to 0 would claim a 0 GB server, so an
178	    // unknown size means no ratio rather than a wrong one.
179	    ramMB: server.gamePlan?.ramMB ?? 0,
180	    installed: live.map((s) => {
181	      const m = byId.get(s.modId);
182	      return { name: m?.name ?? "Unknown mod", fileBytes: m?.fileBytes ?? null, impact: m?.impact ?? "light" };
183	    }),
184	  });
185	
186	  return {
187	    view: { family, variant, categories, installedCount: live.length, busy, gameVersion, load },
188	  };
189	}
190	
191	/** Queue a mod for install on an owned server. */
192	export async function installMod(
193	  serverId: string,
194	  modId: string
195	): Promise<{ error?: string; ok?: boolean }> {
196	  const { user, server } = await ownedServer(serverId);
197	  const family = familyFor(server);
198	  if (!family) return { error: "This server doesn't support mods." };
199	
200	  const mod = await db.gameMod.findUnique({ where: { id: modId } });
201	  if (!mod || !mod.active) return { error: "That mod is unavailable." };
202	  if (mod.gameFamily !== family) return { error: "That mod isn't for this game." };
203	  if (mod.appliesToVariant && server.gameVariant && mod.appliesToVariant !== server.gameVariant) {
204	    return { error: `${mod.name} needs the "${mod.appliesToVariant}" server type.` };
205	  }
206	
207	  /* Refuse here rather than queue a GAME_MOD_SYNC that can only come back
208	     "auto-install isn't wired for this game". The panel already hides the
209	     button for these, so reaching this is a stale page or a direct call — but
210	     an unrunnable job would still take the server's one in-flight slot. */
211	  const support = installSupport(family, mod.source);
212	  if (!support.ok) return { error: support.message };
213	
214	  const existing = await db.serverMod.findUnique({
215	    where: { serverId_modId: { serverId, modId } },
216	  });
217	  if (existing && (existing.status === "INSTALLED" || existing.status === "INSTALLING")) {
218	    return { error: `${mod.name} is already installed.` };
219	  }
220	
221	  if (await hasInflightJob(serverId)) {
222	    return { error: "Another operation is already in progress on this server." };
223	  }
224	
225	  await db.serverMod.upsert({
226	    where: { serverId_modId: { serverId, modId } },
227	    create: { serverId, modId, status: "INSTALLING", error: null },
228	    update: { status: "INSTALLING", error: null },
229	  });
230	  await db.job.create({ data: { type: "GAME_MOD_SYNC", serverId } });
231	  await db.auditLog.create({
232	    data: { userId: user.id, action: "gameserver.mod.install", detail: `${serverId} mod=${mod.slug}` },
233	  });
234	
235	  revalidatePath(`/dashboard/servers/${serverId}`);
236	  return { ok: true };
237	}
238	
239	/** Queue a mod for removal from an owned server. */
240	export async function uninstallMod(
241	  serverId: string,
242	  modId: string
243	): Promise<{ error?: string; ok?: boolean }> {
244	  const { user, server } = await ownedServer(serverId);
245	
246	  const existing = await db.serverMod.findUnique({
247	    where: { serverId_modId: { serverId, modId } },
248	    include: { mod: true },
249	  });
250	  if (!existing || existing.status === "REMOVED") {
251	    return { error: "That mod isn't installed." };
252	  }
253	
254	  if (await hasInflightJob(serverId)) {
255	    return { error: "Another operation is already in progress on this server." };
256	  }
257	
258	  await db.serverMod.update({
259	    where: { serverId_modId: { serverId, modId } },
260	    data: { status: "REMOVING", error: null },
261	  });
262	  await db.job.create({ data: { type: "GAME_MOD_SYNC", serverId } });
263	  await db.auditLog.create({
264	    data: { userId: user.id, action: "gameserver.mod.uninstall", detail: `${serverId} mod=${existing.mod.slug}` },
265	  });
266	
267	  void server; // ownership already enforced above
268	  revalidatePath(`/dashboard/servers/${serverId}`);
269	  return { ok: true };
270	}
271	
272	export type EligibleServer = { id: string; hostname: string; label: string | null; status: string };
273	
274	/**
275	 * Who can "Add to my server" for a given NxLabs catalogue mod, and from
276	 * where — read by the public /mods/[family]/[slug] page AND the logged-in
277	 * /dashboard/nxlabs page (one code path, per NxLabs's own design brief: the
278	 * actual install still only ever happens through installMod() above).
279	 *
280	 * Soft on auth by design — this backs a PUBLIC page anonymous visitors load,
281	 * so "not logged in" is a normal, expected result, not an error.
282	 */
283	export async function getEligibleServersForMod(
284	  modId: string
285	): Promise<{ loggedIn: boolean; servers: EligibleServer[] }> {
286	  const user = await currentUser();
287	  if (!user) return { loggedIn: false, servers: [] };
288	
289	  const mod = await db.gameMod.findUnique({ where: { id: modId } });
290	  if (!mod || !mod.active) return { loggedIn: true, servers: [] };
291	
292	  const candidates = await db.server.findMany({
293	    where: { userId: user.id, status: { notIn: ["DELETING"] } },
294	    include: { osTemplate: true, gamePlan: true },
295	  });
296	
297	  const servers = candidates
298	    .filter((s) => familyFor(s) === mod.gameFamily)
299	    .filter((s) => !mod.appliesToVariant || !s.gameVariant || s.gameVariant === mod.appliesToVariant)
300	    .map((s): EligibleServer => ({ id: s.id, hostname: s.hostname, label: s.label, status: s.status }));
301	
302	  return { loggedIn: true, servers };
303	}
304	
305	/**
306	 * NxLabs ratings/comments (ModRating — see prisma/schema.prisma). One row
307	 * per (userId, gameModId): calling this again just edits the existing row,
308	 * which is what keeps "your rating" and "the comment list" reading from the
309	 * same single table without drifting apart.
310	 */
311	export async function rateMod(
312	  modId: string,
313	  rating: number,
314	  comment: string | null
315	): Promise<{ error?: string; ok?: boolean }> {
316	  const user = await requireUser();
317	  if (!Number.isInteger(rating) || rating < 1 || rating > 5) return { error: "Rating must be 1-5." };
318	
319	  const mod = await db.gameMod.findUnique({ where: { id: modId } });
320	  if (!mod || !mod.active) return { error: "That mod is unavailable." };
321	
322	  const trimmed = comment?.trim() || null;
323	  if (trimmed && trimmed.length > 2000) return { error: "Comment is too long (2000 characters max)." };
324	
325	  await db.modRating.upsert({
326	    where: { userId_gameModId: { userId: user.id, gameModId: modId } },
327	    create: { userId: user.id, gameModId: modId, rating, comment: trimmed },
328	    update: { rating, comment: trimmed },
329	  });
330	
331	  revalidatePath(`/mods/${mod.gameFamily}/${mod.slug}`);
332	  revalidatePath(`/dashboard/nxlabs/${mod.gameFamily}/${mod.slug}`);
333	  return { ok: true };
334	}
335	
336	/** Thin "use server" wrapper so the client-side comment list's "Load more" can call a paginated read (mods-catalog.ts's own functions are plain reads, not server actions). */
337	export async function loadMoreModComments(modId: string, cursor: string): Promise<{ comments: ModComment[]; nextCursor: string | null }> {
338	  return listModComments(modId, { cursor, take: 10 });
339	}
340	
341	/** Admin moderation: blank out a comment's text, keeping the star rating intact. */
342	export async function deleteModComment(ratingId: string): Promise<{ error?: string; ok?: boolean }> {
343	  const admin = await requireAdmin();
344	  const row = await db.modRating.findUnique({ where: { id: ratingId }, include: { gameMod: true } });
345	  if (!row) return { error: "Comment not found." };
346	  if (!row.comment) return { error: "That entry has no comment to remove." };
347	
348	  await db.modRating.update({ where: { id: ratingId }, data: { comment: null } });
349	  await recordAudit(admin.id, "nxlabs.comment.delete", `mod=${row.gameMod.slug} rating=${ratingId}`);
350	
351	  revalidatePath(`/mods/${row.gameMod.gameFamily}/${row.gameMod.slug}`);
352	  revalidatePath(`/dashboard/nxlabs/${row.gameMod.gameFamily}/${row.gameMod.slug}`);
353	  return { ok: true };
354	}
