132	export async function gameConfigApply(job: Job): Promise<void> {
133	  const serverId = job.serverId;
134	  if (!serverId) throw new Error("game config: job has no serverId");
135	
136	  const server = await db.server.findUnique({
137	    where: { id: serverId },
138	    include: { osTemplate: true, gamePlan: true, dedicatedIp: true, node: true },
139	  });
140	  if (!server) throw new Error(`Server ${serverId} not found`);
141	
142	  const family = familyFor(server);
143	  const schema = schemaFor(family);
144	  if (!family || !schema) {
145	    throw new Error(`game config: ${server.hostname} is not a customizable game server`);
146	  }
147	
148	  const variant = server.gameVariant ?? schema.defaultVariant;
149	  const realApply = familyRealApplyEnabled(family);
150	
151	  // -------------------------------------------------------------------------
152	  // Simulation is a SANDBOX affordance and MUST NEVER run in production.
153	  //
154	  // Until 2026-07-26 it did: production has no ENABLE_REAL_GAMECFG, so every real
155	  // customer request fell through to the block below, stamped an `_appliedAt`
156	  // marker, and notified them "Game settings applied on <hostname>" — with the
157	  // "(sandbox)" suffix suppressed, because SANDBOX is false on production. So the
158	  // customer changed their difficulty or slot count, was told it was applied, and
159	  // nothing on the server had changed.
160	  //
161	  // Identical in kind to the SSL bug fixed the same day, where production wrote a
162	  // certificate row as ACTIVE with an invented expiry while no certbot had run:
163	  // the system asserting an outcome it never performed. A change we did not apply
164	  // is a FAILURE, and it must say so loudly enough that an operator notices the
165	  // flag is missing.
166	  // -------------------------------------------------------------------------
167	  if (!realApply && !SANDBOX) {
168	    throw new Error(
169	      "Game settings could not be applied: real application is switched off on this " +
170	        "server (ENABLE_REAL_GAMECFG is not set), so nothing was written to the game " +
171	        "server and your settings are NOT in effect. Please contact support."
172	    );
173	  }
174	
175	  if (!realApply) {
176	    const existing = (server.gameConfig as Record<string, unknown> | null) ?? {};
177	    const marker = {
178	      _appliedVariant: variant,
179	      _appliedAt: new Date().toISOString(),
180	      _configVersion: GAME_CONFIG_VERSION,
181	      _sandbox: SANDBOX,
182	    };
183	
184	    await db.server.update({
185	      where: { id: server.id },
186	      data: { gameConfig: { ...existing, ...marker } as any },
187	    });
188	
189	    await notify(
190	      server.userId,
191	      `Game settings applied on ${server.hostname}`,
192	      `${schema.label} (${variant}) settings were applied${SANDBOX ? " (sandbox)" : ""}.`,
193	      `/dashboard/servers/${server.id}?tab=game settings`
194	    );
195	    return;
196	  }
197	
198	  // -------------------------------------------------------------------------
199	  // REAL PATH — gated behind ENABLE_REAL_GAMECFG. Everything below is wrapped so
200	  // a failure notifies the user but never throws out of the handler.
201	  // -------------------------------------------------------------------------
202	  const existing = (server.gameConfig as Record<string, unknown> | null) ?? {};
203	  const valid = validateConfig(family, existing);
204	  // `existing` also holds the `_`-prefixed markers; validateConfig drops unknown
205	  // keys, so `values` is exactly the schema fields keyed on the game's own keys.
206	  const values = valid.ok ? valid.values : {};
207	
208	  let outcome: ApplyOutcome = { ok: false, applied: [], notes: [] };
209	  try {
210	    outcome = await applyRealConfig(server, family, values);
211	  } catch (e) {
212	    const msg = e instanceof Error ? e.message : String(e);
213	    console.error(`[game-config] real apply failed on ${server.hostname}:`, e);
214	    outcome = { ok: false, applied: [], notes: [`Apply failed: ${msg}`] };
215	  }
216	
217	  // Always record the applied-marker (even on partial/soft failure) so the portal
218	  // reflects the attempt, and note whether the real push succeeded.
219	  const marker = {
220	    _appliedVariant: variant,
221	    _appliedAt: new Date().toISOString(),
222	    _configVersion: GAME_CONFIG_VERSION,
223	    _sandbox: SANDBOX,
224	    _real: true,
225	    _realOk: outcome.ok,
226	  };
227	  try {
228	    await db.server.update({
229	      where: { id: server.id },
230	      data: { gameConfig: { ...existing, ...marker } as any },
231	    });
232	  } catch (e) {
233	    console.error("[game-config] marker update failed", e);
234	  }
235	
236	  const detail = [...outcome.applied, ...outcome.notes].join(" ");
237	  await notify(
238	    server.userId,
239	    outcome.ok
240	      ? `Game settings applied on ${server.hostname}`
241	      : `Game settings partially applied on ${server.hostname}`,
242	    `${schema.label} (${variant}) — ${detail || "no changes were made."}`,
243	    `/dashboard/servers/${server.id}?tab=game settings`
244	  );
245	}
