265	/**
266	 * Connect to the game-server VM (host/port derived exactly like the file manager,
267	 * user "root", password `rootPassword`), run `fn`, and always close the session.
268	 */
269	function withSsh<T>(server: SshServer, fn: (conn: Client, sftp: SFTPWrapper) => Promise<T>): Promise<T> {
270	  return new Promise((resolve, reject) => {
271	    const target = connectionTarget(server as any);
272	    if (!target) {
273	      reject(new Error("server is not reachable yet — connection details are pending"));
274	      return;
275	    }
276	    const password = serverRootPassword(server);
277	    if (!password) {
278	      reject(new Error("server has no root password set"));
279	      return;
280	    }
281	
282	    const conn = new Client();
283	    let settled = false;
284	    const finish = (err: Error | null, val?: T) => {
285	      if (settled) return;
286	      settled = true;
287	      try {
288	        conn.end();
289	      } catch {
290	        /* best-effort */
291	      }
292	      if (err) reject(err);
293	      else resolve(val as T);
294	    };
295	
296	    conn.on("ready", () => {
297	      conn.sftp((err, sftp) => {
298	        if (err) return finish(err);
299	        fn(conn, sftp).then((v) => finish(null, v)).catch((e) => finish(e instanceof Error ? e : new Error(String(e))));
300	      });
301	    });
302	    conn.on("error", (e) => finish(e instanceof Error ? e : new Error(String(e))));
303	    conn.connect({
304	      host: target.host,
305	      port: target.port,
306	      username: "root",
307	      password,
308	      readyTimeout: CONNECT_TIMEOUT_MS,
309	    });
310	  });
311	}
312	
313	/** Read a remote text file, or null if it does not exist. */
314	function sftpRead(sftp: SFTPWrapper, path: string): Promise<string | null> {
315	  return new Promise((resolve, reject) => {
316	    sftp.readFile(path, (err, data) => {
317	      if (err) {
318	        // ENOENT / no such file → null; anything else is a real error.
319	        const code = (err as NodeJS.ErrnoException).code;
320	        if (code === "ENOENT" || code === "No such file" || /no such file/i.test(err.message)) {
321	          return resolve(null);
322	        }
323	        return reject(err);
324	      }
325	      resolve(data.toString("utf8"));
326	    });
327	  });
328	}
329	
330	/** Write a remote text file (overwrites). */
331	function sftpWrite(sftp: SFTPWrapper, path: string, content: string): Promise<void> {
332	  return new Promise((resolve, reject) => {
333	    sftp.writeFile(path, Buffer.from(content, "utf8"), (err) => (err ? reject(err) : resolve()));
334	  });
335	}
336	
337	/** Write a remote binary file (overwrites) — same as sftpWrite but skips utf8 re-encoding. */
338	function sftpWriteBinary(sftp: SFTPWrapper, path: string, content: Buffer): Promise<void> {
339	  return new Promise((resolve, reject) => {
340	    sftp.writeFile(path, content, (err) => (err ? reject(err) : resolve()));
341	  });
342	}
343	
344	/** Run a remote shell command; resolves with stdout/stderr/exit-code (never rejects on non-zero). */
345	function execRemote(conn: Client, cmd: string): Promise<{ code: number; stdout: string; stderr: string }> {
346	  return new Promise((resolve, reject) => {
347	    conn.exec(cmd, (err, stream: ClientChannel) => {
348	      if (err) return reject(err);
349	      let stdout = "";
350	      let stderr = "";
351	      const timer = setTimeout(() => {
352	        try {
353	          stream.close();
354	        } catch {
355	          /* ignore */
356	        }
357	      }, EXEC_TIMEOUT_MS);
358	      stream
359	        .on("close", (code: number) => {
360	          clearTimeout(timer);
361	          resolve({ code: code ?? 0, stdout, stderr });
362	        })
363	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
364	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
365	    });
366	  });
367	}
