525	/**
526	 * Read a container's current environment as a map.
527	 *
528	 * Recreating a container means re-supplying its WHOLE environment, not just the
529	 * keys being changed: the images this is used for get most of their defaults
530	 * from their own Dockerfile `ENV`s, and dropping those would silently reset
531	 * settings the customer never touched. `PATH` is excluded — the image always
532	 * injects a correct one, and carrying ours over would be wrong.
533	 */
534	async function readContainerEnv(conn: Client, container: string): Promise<Map<string, string> | null> {
535	  const inspect = await execRemote(conn, `docker inspect ${container} --format '{{json .Config.Env}}'`);
536	  if (inspect.code !== 0) return null;
537	  let envArr: string[];
538	  try {
539	    envArr = JSON.parse(inspect.stdout.trim());
540	  } catch {
541	    return null;
542	  }
543	  const envMap = new Map<string, string>();
544	  for (const entry of envArr) {
545	    const idx = entry.indexOf("=");
546	    if (idx < 0) continue;
547	    envMap.set(entry.slice(0, idx), entry.slice(idx + 1));
548	  }
549	  envMap.delete("PATH");
550	  return envMap;
551	}
