200	/** Resolve a direct download URL from the source's API (worker-side). */
201	async function resolveUrl(mod: ModRowFull): Promise<string | null> {
202	  const id = mod.sourceId ?? "";
203	  try {
204	    switch (mod.source) {
205	      case "umod":
206	        return `https://umod.org/plugins/${id}.cs`;
207	      case "spigotmc":
208	        return `https://api.spiget.org/v2/resources/${id}/download`;
209	      case "modrinth": {
210	        const loader = modrinthLoader(mod);
211	        const q = loader ? `?loaders=["${loader}"]` : "";
212	        const res = await fetch(`https://api.modrinth.com/v2/project/${id}/version${q}`, {
213	          headers: { "User-Agent": "Nxeon/1.0 (mod-manager)" },
214	        });
215	        if (!res.ok) return null;
216	        const versions = (await res.json()) as Array<{ files: Array<{ url: string; primary: boolean }> }>;
217	        const v = versions[0];
218	        if (!v) return null;
219	        return (v.files.find((f) => f.primary) ?? v.files[0])?.url ?? null;
220	      }
221	      case "thunderstore": {
222	        const [author, ...rest] = id.split("-");
223	        if (!rest.length) return null;
224	        const res = await fetch(`https://thunderstore.io/api/experimental/package/${author}/${rest.join("-")}/`, {
