242	  const key = mod.appliesTo ?? mod.variant ?? "";
243	  const map: Record<string, string> = {
244	    paper: "paper", spigot: "spigot", purpur: "purpur", bukkit: "bukkit",
245	    fabric: "fabric", forge: "forge", neoforge: "neoforge", quilt: "quilt",
246	  };
247	  return map[key] ?? null;
248	}
249	
250	/** Shell snippet that echoes (creating if needed) the mod/plugin dir for family+variant. */
251	/* The shared set in lib/mod-install-support.ts is what the PANEL uses to decide
252	   whether to draw an Install button at all. If this switch ever grows a case
253	   that isn't in that set the button never appears, and if the set grows a
254	   family this switch doesn't handle the button appears and fails — which is the
255	   bug that module was written to end. Fail loudly here rather than let them
256	   drift apart silently. */
257	function modDirShell(family: string, variant: string | null): string | null {
258	  if (!INSTALLABLE_FAMILIES.has(family)) return null;
259	  switch (family) {
260	    case "minecraft": {
261	      const modded = variant && ["fabric", "forge", "neoforge", "quilt"].includes(variant);
262	      const sub = modded ? "mods" : "plugins";
263	      return `root=$(find /opt /srv /home /root -maxdepth 6 -name server.properties -printf '%h\\n' 2>/dev/null | head -1); [ -n "$root" ] && { mkdir -p "$root/${sub}"; echo "$root/${sub}"; }`;
264	    }
265	    case "rust":
266	      return `d=$(find /opt /srv /home -maxdepth 9 -type d \\( -name oxide -o -name carbon \\) 2>/dev/null | head -1); [ -n "$d" ] && { mkdir -p "$d/plugins"; echo "$d/plugins"; }`;
267	    // Was a case-sensitive `find -name BepInEx` — always a no-op even with
268	    // BepInEx installed, since lloesche/valheim-server's own real directory is
269	    // lowercase `bepinex` (confirmed against its README). Use the documented,
270	    // fixed path directly instead of searching for it: `/config` is the
271	    // catalog's own `-v /opt/valheim/config:/config` mount, and the image
272	    // itself watches `/config/bepinex/plugins` for user-added plugins and
273	    // copies them into the real BepInEx plugin dir on boot — this is the
274	    // customer-facing "drop mods here" folder by design, not an internal path.
275	    case "valheim":
276	      return `d=/opt/valheim/config/bepinex/plugins; [ -d /opt/valheim/config/bepinex ] && { mkdir -p "$d"; echo "$d"; }`;
277	    default:
278	      return null;
279	  }
280	}
281	
282	const shq = (s: string) => s.replace(/'/g, "'\\''");
283	
284	async function installModReal(server: SshServer, mod: ModRowFull): Promise<ModResult> {
285	  const target = planTarget(mod);
286	  if (!target) {
287	    return { ok: false, error: `Auto-install isn't available for ${mod.source} mods yet — install manually${mod.url ? ` from ${mod.url}` : ""}.` };
288	  }
289	  const dirShell = modDirShell(mod.gameFamily, mod.variant);
290	  if (!dirShell) {
291	    return { ok: false, error: `Auto-install isn't wired for this game yet.` };
292	  }
293	  if (!RESOLVABLE_SOURCES.has(mod.source)) {
294	    return { ok: false, error: `We can't fetch downloads from ${mod.source} — install this one by hand in Files.` };
295	  }
296	  const url = await resolveUrl(mod);
297	  if (!url) return { ok: false, error: "Could not resolve a download for this mod (it may have moved)." };
298	
299	  let cmd: string;
300	  if (target.kind === "zip") {
301	    cmd =
302	      `dir=$( ${dirShell} ); if [ -z "$dir" ]; then echo NODIR; exit 0; fi; ` +
303	      `tmp=$(mktemp -d); if curl -fsSL --max-time 180 -o "$tmp/m.zip" '${shq(url)}'; then ` +
304	      `rm -rf "$dir/${target.folder}"; mkdir -p "$dir/${target.folder}"; ` +
305	      `unzip -oq "$tmp/m.zip" -d "$dir/${target.folder}" && echo OK || echo UNZIP; rm -rf "$tmp"; else echo FAIL; fi`;
306	  } else {
307	    cmd =
308	      `dir=$( ${dirShell} ); if [ -z "$dir" ]; then echo NODIR; exit 0; fi; ` +
309	      `if curl -fsSL --max-time 180 -o "$dir/${target.file}" '${shq(url)}'; then echo OK; else echo FAIL; fi`;
310	  }
311	
312	  const out = await withSsh(server, (conn) => execRemote(conn, cmd));
313	  const s = out.stdout.trim();
314	  if (s.endsWith("OK")) return { ok: true };
315	  if (s.includes("NODIR")) return { ok: false, error: "Couldn't find the game's mod folder — is the server fully set up?" };
316	  if (s.includes("UNZIP")) return { ok: false, error: "Downloaded the mod but couldn't unpack it (unzip missing?)." };
317	  return { ok: false, error: "Download failed on the server." };
318	}
319	
320	async function removeModReal(server: SshServer, mod: ModRowFull): Promise<ModResult> {
321	  const target = planTarget(mod);
322	  const dirShell = modDirShell(mod.gameFamily, mod.variant);
323	  if (!target || !dirShell) return { ok: true }; // nothing we placed → nothing to remove
324	  const rm =
325	    target.kind === "zip"
326	      ? `dir=$( ${dirShell} ); [ -n "$dir" ] && rm -rf "$dir/${target.folder}"; echo OK`
327	      : `dir=$( ${dirShell} ); [ -n "$dir" ] && rm -f "$dir/${target.file}"; echo OK`;
328	  await withSsh(server, (conn) => execRemote(conn, rm));
329	  return { ok: true };
330	}
331	
332	// --- SSH transport (root@VM, password from the same source as the file manager) ---
333	
334	type ModRowFull = ModRow & { variant: string | null; appliesTo: string | null };
335	
336	function withSsh<T>(server: SshServer, fn: (conn: Client) => Promise<T>): Promise<T> {
337	  return new Promise((resolve, reject) => {
338	    const t = connectionTarget(server as any);
339	    if (!t) return reject(new Error("server is not reachable yet"));
340	    const password = serverRootPassword(server as any);
341	    if (!password) return reject(new Error("server has no root password set"));
342	    const conn = new Client();
343	    let settled = false;
344	    const finish = (err: Error | null, val?: T) => {
345	      if (settled) return;
346	      settled = true;
347	      try { conn.end(); } catch { /* best-effort */ }
348	      err ? reject(err) : resolve(val as T);
349	    };
350	    conn.on("ready", () => {
351	      fn(conn).then((v) => finish(null, v)).catch((e) => finish(e instanceof Error ? e : new Error(String(e))));
352	    });
353	    conn.on("error", (e) => finish(e instanceof Error ? e : new Error(String(e))));
354	    conn.connect({ host: t.host, port: t.port, username: "root", password, readyTimeout: CONNECT_TIMEOUT_MS });
355	  });
356	}
357	
358	function execRemote(conn: Client, cmd: string): Promise<{ code: number; stdout: string; stderr: string }> {
359	  return new Promise((resolve, reject) => {
360	    conn.exec(cmd, (err, stream: ClientChannel) => {
361	      if (err) return reject(err);
362	      let stdout = "";
363	      let stderr = "";
364	      const timer = setTimeout(() => { try { stream.close(); } catch { /* ignore */ } }, EXEC_TIMEOUT_MS);
365	      stream
366	        .on("close", (code: number) => { clearTimeout(timer); resolve({ code: code ?? 0, stdout, stderr }); })
367	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
368	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
369	    });
370	  });
371	}
