100	/** Real average+count per mod, one groupBy query for as many mods as needed at once. */
101	async function ratingAggs(modIds: string[]): Promise<Map<string, RatingAgg>> {
102	  if (modIds.length === 0) return new Map();
103	  const rows = await db.modRating.groupBy({
104	    by: ["gameModId"],
