169	export type CatalogSort = "featured" | "downloads" | "latest" | "rating";
170	
171	export type CatalogPage = {
172	  mods: ModSummary[];
173	  total: number;
174	  page: number;
175	  totalPages: number;
176	  perPage: number;
177	};
