179	/**
180	 * Every scalar `orderBy` StoreBrowser's sort tabs can ask for. "rating" is
181	 * the one honest exception: avgRating is computed from a separate ModRating
182	 * table with no cached column on GameMod, and Prisma's relation-aggregate
183	 * `orderBy` only supports `_count` (not `_avg`) for to-many relations — there
184	 * is no cheap DB-side "top rated" ordering to give it. Fetching by downloads
185	 * and re-sorting by rating WITHIN each page (below) is a documented
186	 * approximation: "Top Rated" page 2 shows the 25th-48th most-downloaded mods
187	 * re-ordered by rating, not the true 25th-48th highest-rated mods
188	 * catalogue-wide. That is honest and fine at today's rating volumes (a small
189	 * fraction of 32k+ mods have any reviews at all); if ratings ever justify
190	 * it, add a cached avgRating/ratingCount column on GameMod (maintained by
191	 * the rating mutation) and give this its own real orderBy.
192	 */
193	const ORDER_BY: Record<CatalogSort, Prisma.GameModOrderByWithRelationInput[]> = {
194	  featured: [{ featured: "desc" }, { downloads: "desc" }, { popularity: "desc" }, { name: "asc" }],
195	  downloads: [{ downloads: "desc" }, { name: "asc" }],
196	  latest: [{ createdAt: "desc" }],
197	  rating: [{ downloads: "desc" }, { name: "asc" }],
198	};
