292	    where: { active: true, upstreamOk: true, gameFamily: mod.gameFamily, id: { not: mod.id } },
293	    orderBy: [{ downloads: "desc" }, { popularity: "desc" }],
294	    take: take * 3, // over-fetch a little so the same-category re-sort below has real options
295	  });
