344	
345	export type RecommendedPlan = { planName: string; ramMB: number; priceCents: number } | null;
346	
347	/**
348	 * Simple, honest heuristic (Phase 1 scope — no per-mod resource profiling):
349	 * light-impact mods run on any active plan for the family; moderate needs at
350	 * least 2GB; heavy needs at least 4GB. Returns the CHEAPEST active GamePlan
351	 * for the family that clears the bar, or null if none does (never guesses a
352	 * number that isn't a real, active, orderable plan).
353	 */
354	export function recommendedPlanFor(mod: { impact: string }, gamePlans: Pick<GamePlan, "name" | "ramMB" | "priceCents" | "active">[]): RecommendedPlan {
355	  const minRamMB = mod.impact === "heavy" ? 4096 : mod.impact === "moderate" ? 2048 : 0;
356	  const candidates = gamePlans.filter((p) => p.active && p.ramMB >= minRamMB).sort((a, b) => a.priceCents - b.priceCents);
357	  const pick = candidates[0];
358	  return pick ? { planName: pick.name, ramMB: pick.ramMB, priceCents: pick.priceCents } : null;
359	}
