361	export function formatDownloads(n: number | null): string | null {
362	  if (n == null) return null;
363	  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(n >= 10_000_000 ? 0 : 1)}M`;
364	  if (n >= 1_000) return `${(n / 1_000).toFixed(n >= 10_000 ? 0 : 1)}K`;
365	  return String(n);
366	}
367	
368	export function formatBytes(bytes: number | null): string | null {
369	  if (!bytes || bytes <= 0) return null;
370	  if (bytes >= 1024 ** 3) return `${(bytes / 1024 ** 3).toFixed(1)} GB`;
371	  if (bytes >= 1024 * 1024) return `${Math.round(bytes / (1024 * 1024))} MB`;
372	  return `${Math.max(1, Math.round(bytes / 1024))} KB`;
373	}
