375	/**
376	 * The real, authoritative download for a mod detail page. Prefers the
377	 * source's own direct file URL (same resolution `worker/game-mods.ts` uses to
378	 * install it) so a visitor gets the actual file, not just a landing page;
379	 * falls back to the mod's own project/resource page (still the real,
380	 * authoritative source — never a Nxeon-hosted mirror) when the source can't
381	 * be resolved live or isn't one of the three we know how to resolve.
382	 */
383	export async function resolveDownloadUrl(mod: Pick<GameMod, "source" | "sourceId" | "appliesToVariant" | "url">): Promise<{ url: string; direct: boolean } | null> {
384	  const fallback = mod.url ? { url: mod.url, direct: false } : null;
385	  const id = mod.sourceId ?? "";
386	  if (!id) return fallback;
387	  const UA = "Nxeon/1.0 (nxlabs-catalog)";
388	  try {
389	    if (mod.source === "modrinth") {
390	      const headers: Record<string, string> = { "User-Agent": UA };
391	      if (process.env.MODRINTH_API_KEY) headers.Authorization = process.env.MODRINTH_API_KEY;
392	      const res = await fetch(`https://api.modrinth.com/v2/project/${encodeURIComponent(id)}/version`, { headers, next: { revalidate: 3600 } });
393	      if (!res.ok) return fallback;
394	      const versions = (await res.json()) as Array<{ files: Array<{ url: string; primary: boolean }> }>;
395	      const v = versions[0];
396	      const file = v ? (v.files.find((f) => f.primary) ?? v.files[0]) : null;
397	      return file ? { url: file.url, direct: true } : fallback;
398	    }
399	    if (mod.source === "spigotmc") {
400	      // Spiget's own download endpoint 302s to the real jar — genuinely direct.
401	      return { url: `https://api.spiget.org/v2/resources/${encodeURIComponent(id)}/download`, direct: true };
402	    }
403	    if (mod.source === "thunderstore") {
404	      const [namespace, ...rest] = id.split("-");
405	      if (!namespace || !rest.length) return fallback;
406	      const res = await fetch(`https://thunderstore.io/api/experimental/package/${encodeURIComponent(namespace)}/${encodeURIComponent(rest.join("-"))}/`, {
407	        headers: { "User-Agent": UA },
408	        next: { revalidate: 3600 },
409	      });
410	      if (!res.ok) return fallback;
411	      const pkg = (await res.json()) as { latest?: { download_url?: string } };
412	      return pkg.latest?.download_url ? { url: pkg.latest.download_url, direct: true } : fallback;
413	    }
414	  } catch {
415	    return fallback;
416	  }
417	  return fallback;
418	}
